import test from 'node:test';import assert from 'node:assert/strict';import{rumorLines,rumorBox}from'../field-rumor-art.js';
test('overheard text wraps into at most three short readable lines',()=>{const measure=s=>s.length*6;for(const text of ['Mara: A sound carries from the listening point.',Array.from({length:70},()=> 'waterline').join(' ')]){const lines=rumorLines(text,measure,180);assert.ok(lines.length<=3);assert.ok(lines.every(s=>measure(s)<=180));}assert.ok(rumorLines('one '.repeat(100),measure,180).at(-1).endsWith('…'));});
test('world-space captions stay inside portrait and landscape clear play areas',()=>{for(const view of [{left:0,right:320,top:112,bottom:620},{left:-500,right:900,top:-160,bottom:220}])for(const[x,y]of [[-600,-600],[0,0],[1000,1000]]){const b=rumorBox({x,y,width:260,height:68,view});assert.ok(b.x>=view.left+8);assert.ok(b.x+b.w<=view.right-8);assert.ok(b.y>=view.top+8);assert.ok(b.y+b.h<=view.bottom-12);}});
